export type ParsedRebalanceSwapInstruction<
  TProgram extends string = typeof STOCKPILOT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    /** Vault owner or the approved keeper; checked in the handler. */
    authority: TAccountMetas[0];
    vault: TAccountMetas[1];
    config: TAccountMetas[2];
    pool: TAccountMetas[3];
    fromMint: TAccountMetas[4];
    toMint: TAccountMetas[5];
    vaultFromAccount: TAccountMetas[6];
    vaultToAccount: TAccountMetas[7];
    poolFromAccount: TAccountMetas[8];
    poolToAccount: TAccountMetas[9];
    tokenProgram: TAccountMetas[10];
  };
  data: RebalanceSwapInstructionData;
};

export function parseRebalanceSwapInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedRebalanceSwapInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 11) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 11,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      authority: getNextAccount(),
      vault: getNextAccount(),
      config: getNextAccount(),
      pool: getNextAccount(),
      fromMint: getNextAccount(),
      toMint: getNextAccount(),
      vaultFromAccount: getNextAccount(),
      vaultToAccount: getNextAccount(),
      poolFromAccount: getNextAccount(),
      poolToAccount: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getRebalanceSwapInstructionDataDecoder().decode(instruction.data),
  };
}
